import React, { useEffect, useState } from 'react';
import { getStudentResult } from '../api/api';

function ResultCard({ studentId, onBack }) {
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (studentId) fetchResult();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [studentId]);

  async function fetchResult() {
    setLoading(true);
    setError(null);
    try {
      const data = await getStudentResult(studentId);
      setResult(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  if (loading) return <div className="state-message">Loading result...</div>;
  if (error) {
    return (
      <div className="state-message error">
        {error}
        <div style={{ marginTop: '0.75rem' }}>
          <button onClick={onBack}>Back</button>
        </div>
      </div>
    );
  }
  if (!result) return null;

  const { student, subjects, total_obtained, total_max, percentage, grade, overall_status } = result;

  return (
    <div className="card report-card">
      <div className="report-header">
        <h2>Report Card</h2>
        <button className="btn-secondary" onClick={onBack}>Back</button>
      </div>

      <div className="student-info">
        <div><strong>Name:</strong> {student.name}</div>
        <div><strong>Roll No:</strong> {student.roll_no}</div>
        <div><strong>Class:</strong> {student.class}</div>
      </div>

      <div className="table-wrapper">
        <table>
          <thead>
            <tr>
              <th>Subject</th>
              <th>Marks Obtained</th>
              <th>Max Marks</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {subjects.map((s, idx) => (
              <tr key={idx}>
                <td>{s.subject}</td>
                <td>{s.marks_obtained}</td>
                <td>{s.max_marks}</td>
                <td className={s.status === 'Pass' ? 'pass' : 'fail'}>{s.status}</td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr>
              <td><strong>Total</strong></td>
              <td colSpan={2}><strong>{total_obtained} / {total_max}</strong></td>
              <td></td>
            </tr>
          </tfoot>
        </table>
      </div>

      <div className="result-summary">
        <div className="summary-box">
          <span className="summary-label">Percentage</span>
          <span className="summary-value">{percentage}%</span>
        </div>
        <div className="summary-box">
          <span className="summary-label">Grade</span>
          <span className="summary-value">{grade}</span>
        </div>
        <div className="summary-box">
          <span className="summary-label">Result</span>
          <span className={`summary-value ${overall_status === 'PASS' ? 'pass' : 'fail'}`}>{overall_status}</span>
        </div>
      </div>
    </div>
  );
}

export default ResultCard;
